// 生成 MV/MZ 测试数据（按编辑器的 JSON 排版：数据库每条一行，地图 events 每个事件一行）
import { mkdirSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const out = join(dirname(fileURLToPath(import.meta.url)), 'mz');
mkdirSync(out, { recursive: true });
const db = (rows) => `[\n${rows.map((r) => JSON.stringify(r)).join(',\n')}\n]`;
const cmd = (code, indent, parameters) => ({ code, indent, parameters });

const list = [
  cmd(101, 0, ['Actor1', 0, 0, 2, 'リード']),
  cmd(401, 0, ['こんにちは、旅の人。']),
  cmd(401, 0, ['\\C[2]この村\\C[0]へようこそ！']),
  cmd(102, 0, [['はい', 'いいえ'], 1, 0, 2, 0]),
  cmd(402, 0, [0, 'はい']),
  cmd(101, 1, ['', 0, 0, 2, '']),
  cmd(401, 1, ['ありがとう！']),
  cmd(0, 1, []),
  cmd(402, 0, [1, 'いいえ']),
  cmd(0, 1, []),
  cmd(404, 0, []),
  cmd(105, 0, [2, false]),
  cmd(405, 0, ['遠い昔……']),
  cmd(108, 0, ['コメント']),
  cmd(355, 0, ['$gameVariables.setValue(1, "テキスト");']),
  cmd(655, 0, ["// 注释里的 'x' 不提取"]),
  cmd(356, 0, ['ShowInfo こんにちは']),
  cmd(357, 0, ['TextPlugin', 'show', 'テキスト表示', { text: 'プラグインの文字', count: '3', list: '["一","二"]', struct: '{"title":"題名","on":"true"}' }]),
  cmd(320, 0, [1, 'リード']),
  cmd(122, 0, [3, 3, 0, 4, '"Normal"']),
  cmd(111, 0, [12, '$gameVariables.value(3) === "Normal"']),
  cmd(0, 1, []),
  cmd(412, 0, []),
  cmd(0, 0, []),
];

const map = {
  autoplayBgm: false, autoplayBgs: false, battleback1Name: '', bgm: { name: '', pan: 0, pitch: 100, volume: 90 },
  disableDashing: false, displayName: 'はじまりの村', encounterList: [], encounterStep: 30, height: 13,
  note: '<NoTag>', parallaxName: '', scrollType: 0, tilesetId: 1, width: 17, data: [0, 0, 1.5],
  events: [null, { id: 1, name: '村人A', note: '', pages: [{ list }, { list: [cmd(101, 0, ['', 0, 0, 2]), cmd(401, 0, ['またね']), cmd(0, 0, [])] }], x: 3, y: 4 }, null],
};
const mapText = JSON.stringify(map).replace('"events":' + JSON.stringify(map.events),
  '"events":' + `[\n${map.events.map((e) => JSON.stringify(e)).join(',\n')}\n]`);
writeFileSync(join(out, 'Map001.json'), mapText);

writeFileSync(join(out, 'Actors.json'), db([null,
  { id: 1, battlerName: 'Actor1_1', characterIndex: 0, name: 'リード', nickname: '若き勇者', note: '', profile: '勇敢な少年。\n剣が得意。' },
  { id: 2, battlerName: '', characterIndex: 0, name: '', nickname: '', note: '', profile: '' }]));
writeFileSync(join(out, 'Items.json'), db([null,
  { id: 1, animationId: 41, description: 'HPを500回復する。', name: 'ポーション', note: '<Help:薬>', price: 50 }]));
writeFileSync(join(out, 'CommonEvents.json'), db([null,
  { id: 1, list: [cmd(101, 0, ['', 0, 0, 2]), cmd(401, 0, ['共通イベント']), cmd(0, 0, [])], name: '共通', switchId: 1, trigger: 0 },
  // 公共事件菜单类插件：事件名显示为菜单项，注释中的标签块是说明文字
  { id: 2, name: 'Return Home', switchId: 1, trigger: 0, list: [
    cmd(108, 0, ['<Help Description>']), cmd(408, 0, ['Select your travel destination!']), cmd(408, 0, ['</Help Description>']),
    cmd(408, 0, ['<Subtext>']), cmd(408, 0, ['     - Requirements -']), cmd(408, 0, ['</Subtext>']),
    cmd(108, 0, ['开发者备注：传送后刷新地图']), cmd(408, 0, ['-----']),
    cmd(101, 0, ['', 0, 0, 2]), cmd(401, 0, ['\\n<Lucy>\\n[1]～♥️']), cmd(0, 0, [])] }]));
writeFileSync(join(out, 'Troops.json'), db([null,
  { id: 1, members: [], name: 'スライム*2', pages: [{ conditions: {}, list: [cmd(101, 0, ['', 0, 0, 2]), cmd(401, 0, ['スライムが現れた！']), cmd(0, 0, [])], span: 0 }] }]));
writeFileSync(join(out, 'System.json'), JSON.stringify({
  advanced: { gameId: 1 }, armorTypes: ['', '一般防具'], currencyUnit: 'G', elements: ['', '物理', '炎'],
  equipTypes: ['', '武器', '盾'], gameTitle: 'テストゲーム', skillTypes: ['', '魔法'],
  terms: { basic: ['レベル', 'Lv'], commands: ['戦う', '逃げる', null], params: ['最大HP'], messages: { actionFailure: '%1には効かなかった！', alwaysDash: '常時ダッシュ' } },
  weaponTypes: ['', '剣'], switches: ['', 'スイッチ1'], variables: ['', '変数1'],
}));
writeFileSync(join(out, 'plugins.js'), `// Generated by RPG Maker.
// Do not edit this file directly.
var $plugins =
[
${[
  { name: 'TitleCommand', status: true, description: 'タイトル', parameters: { 'Command Name': 'オプション', 'Visible': 'true', 'Width': '240', 'Items': '["{\\"label\\":\\"開始\\",\\"symbol\\":\\"start\\"}"]' } },
  { name: 'Disabled', status: false, description: '', parameters: {} },
].map((p) => JSON.stringify(p)).join(',\n')}
];
`);
console.log('MV/MZ fixtures written to', out);
